root=Path(__file__).resolve().parents[1];src=Image.open(root/'animation_lab/two_pose_walk/step_a.png').convert('RGBA');a=np.array(src);h,w=a.shape[:2];Y,X=np.indices((h,w))
white=(a[:,:,:3].min(axis=2)>245).astype('uint8');_,labels,_,_=cv2.connectedComponentsWithStats(white,8);a[:,:,3]=np.where(labels==labels[0,0],0,255)
boundary=np.interp(np.arange(w),[0,260,300,350,400,480,550,620,700,750,975],[800,905,918,934,945,951,947,938,918,897,800])[None,:];a[:,:,3]=np.where(Y>boundary,0,a[:,:,3]);body=Image.fromarray(a)
